const PER = 25, KEY = 'template-grid-v3';
let st = { page:0, on:{} };
try { const s = JSON.parse(localStorage.getItem(KEY) || 'null'); if (s && s.on) st = s; } catch(e){}
const save = () => { try { localStorage.setItem(KEY, JSON.stringify(st)); } catch(e){} };
const $ = id => document.getElementById(id);
const PAGES = Math.ceil(CARDS.length / PER);
$('pages').textContent = PAGES;

function chips(c){
  const sw = '<span class="sw">' + [c.c1, c.ink, c.accent, c.support].map(h => '<i style="background:'+h+'"></i>').join('') + '</span>';
  return sw + '<span class="chip">'+c.family+'</span><span class="chip">'+c.layout+'</span><span class="chip">'+c.cat+'</span>';
}
function tile(c, idx){
  const d = document.createElement('div');
  d.className = 'card' + (st.on[c.id] ? ' on' : '');
  d.tabIndex = 0;
  d.innerHTML = (idx !== undefined ? '<span class="key mono">'+(idx+1)+'</span>' : '')
    + '<div class="tick">✓</div><img src="'+c.src+'" alt="'+c.name+'" loading="lazy">'
    + '<div class="meta"><span class="nm">'+c.name+'</span>'+chips(c)+'<span class="id mono">'+c.id+'</span></div>';
  const toggle = () => { if (st.on[c.id]) delete st.on[c.id]; else st.on[c.id] = 1; save(); d.classList.toggle('on', !!st.on[c.id]); count(); };
  d.onclick = toggle;
  d.onkeydown = e => { if (e.key === ' ' || e.key === 'Enter'){ e.preventDefault(); toggle(); } };
  return d;
}
function count(){
  $('nkept').textContent = Object.keys(st.on).length;
  $('pg').textContent = st.page + 1;
  $('bar').style.width = ((st.page + 1) / PAGES * 100) + '%';
}
function render(){
  const g = $('grid'); g.innerHTML = '';
  CARDS.slice(st.page*PER, st.page*PER + PER).forEach((c, i) => g.appendChild(tile(c, i)));
  $('prev').disabled = st.page === 0;
  $('next').textContent = st.page >= PAGES - 1 ? 'Last page' : 'Next twenty-five →';
  count(); window.scrollTo({ top:0 });
}
function showReview(){
  $('pick').style.display = 'none'; $('review').style.display = 'flex';
  ['prev','next','done'].forEach(id => $(id).style.display = 'none');
  ['back','copy'].forEach(id => $(id).style.display = '');
  const kg = $('keptgrid'); kg.innerHTML = '';
  const kept = CARDS.filter(c => st.on[c.id]);
  kept.forEach(c => kg.appendChild(tile(c)));
  $('keptcount').textContent = kept.length + ' approved';
  $('out').value = kept.map(c => c.id + '  ' + c.name + ' · ' + c.family + ' · ' + c.layout + ' · ' + c.cat).join('\n') || 'Nothing approved yet.';
}
function showPick(){
  $('review').style.display = 'none'; $('pick').style.display = '';
  ['prev','next','done'].forEach(id => $(id).style.display = '');
  ['back','copy'].forEach(id => $(id).style.display = 'none');
  render();
}
$('prev').onclick = () => { if (st.page > 0){ st.page--; save(); render(); } };
$('next').onclick = () => { if (st.page < PAGES - 1){ st.page++; save(); render(); } };
$('done').onclick = showReview;
$('back').onclick = showPick;
$('reset').onclick = () => { st = { page:0, on:{} }; save(); showPick(); };
$('copy').onclick = async () => {
  try { await navigator.clipboard.writeText($('out').value); $('copy').textContent = 'Copied'; }
  catch(e){ $('out').select(); $('copy').textContent = 'Select and copy'; }
  setTimeout(() => $('copy').textContent = 'Copy list', 1600);
};
window.addEventListener('keydown', e => {
  if ($('review').style.display === 'flex') return;
  if (e.key === 'ArrowRight') $('next').click();
  else if (e.key === 'ArrowLeft') $('prev').click();
  else if (e.key === 'Enter') showReview();
});
render();
